Rule.Source:

import sailpoint.object.Identity;
import sailpoint.object.Filter;
import sailpoint.object.QueryOptions;
import sailpoint.tools.GeneralException;
import java.util.List;

// Only run this logic for subgroups of "Departments"
if (group != null && group.getParent() != null && "Departments".equals(group.getParent().getDisplayableName())) {

  // Check if the group already has an owner. If so, do nothing.
  if (group.getOwner() != null) {
    log.info("Group '" + group.getDisplayableName() + "' already has an owner. Skipping owner assignment.");
    return;
  }

  log.info("Starting 'Set Department Group Owner on Refresh' rule for group: " + group.getDisplayableName());

  try {
    // Get the name of the group. This should match the department name.
    String departmentName = group.getDisplayableName();
    if (departmentName == null || departmentName.isEmpty()) {
      log.warn("Group name is null or empty. Cannot determine department to query.");
      return;
    }

    log.debug("Searching for a manager in department: " + departmentName);

    // Create a query to find users who are managers in the specified department.
    QueryOptions qo = new QueryOptions();

    // Filter 1: Identity's 'department' attribute must match the group name.
    Filter departmentFilter = Filter.eq("department", departmentName);

    // Filter 2: Identity's 'title' attribute must contain the word "Manager".
    Filter managerFilter = Filter.like("title", "Manager", Filter.MatchMode.ANYWHERE);

    // Combine the filters with an AND condition.
    qo.addFilter(Filter.and(departmentFilter, managerFilter));

    // We only need the first result.
    qo.setResultLimit(1);

    List<Identity> managers = context.getObjects(Identity.class, qo);

    if (managers != null && !managers.isEmpty()) {
      Identity owner = managers.get(0);
      group.setOwner(owner);
      log.info("Successfully set '" + owner.getDisplayableName() + "' as the owner for group '" + group.getDisplayableName() + "'.");
    } else {
      log.warn("No manager found for department '" + departmentName + "'. Owner for group '" + group.getDisplayableName() + "' was not set.");
    }

  } catch (GeneralException e) {
    log.error("Error in 'Set Department Group Owner on Refresh' rule: " + e.getMessage(), e);
  }

  log.info("Finished 'Set Department Group Owner on Refresh' rule for group: " + group.getDisplayableName());
}
